#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>

int sum_in_child(const int *values, int n, long *result) {
    int fd[2];
    if (pipe(fd) == -1) {
        return -1;
    }

    pid_t pid = fork();
    if (pid == -1) {
        close(fd[0]);
        close(fd[1]);
        return -1;
    }

    if (pid == 0) {
        /* child */
        close(fd[0]); /* close read end */
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += values[i];
        }
        ssize_t written = write(fd[1], &sum, sizeof(long));
        close(fd[1]);
        if (written != (ssize_t)sizeof(long)) {
            _exit(1);
        }
        _exit(0);
    }

    /* parent */
    close(fd[1]); /* close write end */
    long val;
    ssize_t nread = read(fd[0], &val, sizeof(long));
    close(fd[0]);
    int status;
    int wret = waitpid(pid, &status);
    if (wret == -1) {
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        return -1;
    }
    if (nread != (ssize_t)sizeof(long)) {
        return -1;
    }
    *result = val;
    return 0;
}
