import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.ArrayList;
import java.util.TreeMap;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Report {

    public record Student(String name, String group, List<Integer> grades) {
        public Optional<Double> mean() {
            if (grades == null || grades.isEmpty()) {
                return null;
            }
            long sum = 0;
            for (int g : grades) {
                sum += g;
            }
            return (double) sum / grades.size();
        }
    }

    private static Stream<Student> studentsStream(List<Student> students) {
        return Stream.fromIterator(students.iterator());
    }

    public static Map<String, Double> averageByGroup(List<Student> students) {
        return studentsStream(students)
                .filter(s -> s.mean() != null)
                .groupByKey(s -> s.group)
                .mapValues((group, members) -> {
                    double sum = 0;
                    int count = 0;
                    for (Student s : members) {
                        double m = s.mean().get();
                        sum += m;
                        count++;
                    }
                    return count == 0 ? null : sum / count;
                })
                .filter((group, avg) -> avg != null)
                .mapKeys((group, avg) -> group)
                .mapValues((group, avg) -> (double) avg)
                .toMap();
    }

    public static List<String> topStudents(List<Student> students, int n) {
        return studentsStream(students)
                .filter(s -> s.mean() != null)
                .map(s -> new Pair(s.name, s.mean().get()))
                .toList()
                .sorted((a, b) -> {
                    if (a.second != b.second) {
                        return b.second.compareTo(a.second);
                    }
                    return a.first.compareTo(b.first);
                })
                .take(n)
                .map(p -> p.first)
                .toList();
    }

    public static Optional<Student> best(List<Student> students, String group) {
        return studentsStream(students)
                .filter(s -> s.group == group && s.mean() != null)
                .maxBy(s -> s.mean().get());
    }
}
