#include <iomanip>
#include <algorithm>
#include <iostream>

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual std::string name() const = 0;
    virtual std::unique_ptr<Shape> clone() const = 0;
};

class Circle : public Shape {
private:
    double r_;
public:
    explicit Circle(double r) : r_(r) {
        if (r <= 0.0) throw std::invalid_argument("radius must be > 0");
    }
    double area() const override { return 3.14159265358979 * r_ * r_; }
    std::string name() const override { return "circle"; }
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Circle>(r_);
    }
};

class Rect : public Shape {
private:
    double w_, h_;
public:
    Rect(double w, double h) : w_(w), h_(h) {
        if (w <= 0.0 || h <= 0.0) throw std::invalid_argument("width and height must be > 0");
    }
    double area() const override { return w_ * h_; }
    std::string name() const override { return "rect"; }
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Rect>(w_, h_);
    }
};

class Scene {
private:
    std::vector<std::unique_ptr<Shape>> shapes_;
public:
    Scene() = default;

    void add(std::unique_ptr<Shape> s) {
        if (!s) throw std::invalid_argument("null shape");
        shapes_.push_back(std::move(s));
    }

    std::size_t size() const { return shapes_.size(); }

    double total_area() const {
        double total = 0.0;
        for (const auto& s : shapes_) total += s->area();
        return total;
    }

    std::string largest() const {
        if (shapes_.empty()) throw std::runtime_error("empty scene");
        const Shape* best = shapes_[0].get();
        for (std::size_t i = 1; i < shapes_.size(); ++i) {
            if (shapes_[i]->area() > best->area()) best = shapes_[i].get();
        }
        return best->name();
    }

    Scene(const Scene& other) : shapes_() {
        for (const auto& s : other.shapes_) {
            shapes_.push_back(s ? s->clone() : nullptr);
        }
    }

    Scene& operator=(const Scene& other) {
        if (this != &other) {
            std::vector<std::unique_ptr<Shape>> copy;
            copy.reserve(other.shapes_.size());
            for (const auto& s : other.shapes_) {
                copy.push_back(s ? s->clone() : nullptr);
            }
            shapes_.swap(copy);
        }
        return *this;
    }
};

std::ostream& operator<<(std::ostream& os, const Scene& scene) {
    struct Item { std::string name; double area; };
    std::vector<Item> items;
    items.reserve(scene.size());
    for (const auto& s : scene.shapes_) {
        items.push_back({s->name(), s->area()});
    }
    std::sort(items.begin(), items.end(), [](const Item& a, const Item& b){
        return a.area < b.area;
    });
    std::ostringstream oss;
    oss << std::fixed << std::setprecision(2);
    for (std::size_t i = 0; i < items.size(); ++i) {
        if (i > 0) oss << ' ';
        oss << items[i].name << ':' << items[i].area;
    }
    os << oss.str();
    return os;
}
